L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colore la barre de vie selon la vie restante plutôt qu'avec une couleur unie. Classique passe du vert à pleine vie au jaune puis au rouge à vide. Couleurs personnalisées mélange les trois nuanciers de cette ligne -- plein (100%), moitié (50%) et vide (0%). Réactif à la classe affiche la couleur de classe à pleine vie, puis glisse vers les couleurs 50% et 0% à mesure que l'unité subit des dégâts. Désactivé laisse les nuanciers Couleur de remplissage unie aux commandes ; dans tous les cas, le Dégradé ci-dessous s'applique toujours, à partir de la couleur choisie ici."
L["Colors allied player bars using their class. Group/raid members are identified automatically; other allies are learned from target, mouseover or focus."] = "Colore les barres des joueurs alliés selon leur classe. Les membres du groupe/raid sont identifiés automatiquement ; les autres alliés sont appris via la cible, le survol ou la focalisation."
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Colore le niveau d'une unité attaquable selon la difficulté, comme l'interface par défaut."
L["Colors group and raid member names inside Say, Yell, Party and Raid messages."] = "Colore les noms des membres du groupe et du raid dans les messages Dire, Crier, Groupe et Raid."
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Colore le texte de niveau selon la difficulté, du gris (insignifiant) au vert, jaune et orange jusqu'au rouge (5 niveaux ou plus au-dessus de vous)."
L["Colors the bar text instead of the fill when the threshold applies."] = "Colore le texte de la barre au lieu du remplissage quand le seuil s'applique."
L["Colors the cast segment during which your interrupt will be available."] = "Colore le segment de l'incantation pendant lequel votre interruption sera disponible."
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "Colore les bordures de type de dissipation avec vos Couleurs de dissipation au lieu de celles de Blizzard."
L["Colors the number by threat status. Off shows it in white."] = "Colore le nombre selon l'état de menace. Désactivé l'affiche en blanc."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "Colore le nombre quand les emplacements libres passent sous cette valeur ; le nuancier choisit la couleur. Zéro le désactive."
L["Colors the strip behind the target's name by its reaction."] = "Colore la bande derrière le nom de la cible selon sa réaction."
