L["Hold the key to open, release to fire. Toggle mode keeps the menu open: the Select key fires, the menu key or Escape closes."] = "Maintenez la touche pour ouvrir, relâchez pour lancer. Le mode bascule garde le menu ouvert : la touche Sélection lance, la touche du menu ou Échap ferme."
