L["Shows the stock rune or combo point frame here instead of the pips."] = "Affiche ici le cadre standard des runes ou points de combo au lieu des pastilles."
L["Shows the unit's level in the frame's level circle, as the default UI does."] = "Affiche le niveau de l'unité dans le cercle de niveau du cadre, comme l'interface par défaut."
L["Shows your arena opponents. Left click targets, right click sets focus."] = "Affiche vos adversaires d'arène. Clic gauche pour cibler, clic droit pour définir la focalisation."
