L["The bank opens anywhere from the Bags header; away from a banker it shows the last saved contents."] = "La banque s'ouvre n'importe où depuis l'en-tête des sacs ; loin d'un banquier, elle affiche le dernier contenu enregistré."
L["The bar shows stacks out of the maximum instead of time."] = "La barre affiche les cumuls sur le maximum au lieu du temps."
L["The bar this page edits."] = "La barre modifiée par cette page."
L["The Combat Indicator is not available for the Focus frame."] = "L'indicateur de combat n'est pas disponible pour le cadre de focalisation."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "L'inverse exact de Chevauchée céleste (en vol) : tout ce qui n'est pas en vol sur une monture capable de planer ou en forme de vol, y compris au sol."
L["The fallback must differ from\nthe main anchor target"] = "Le repli doit être différent de\nla cible d'ancrage principale"
L["the Frame Source to be EllesmereUI"] = "la source de cadre doit être EllesmereUI"
L["The gem could not be socketed."] = "La gemme n'a pas pu être sertie."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "La ligne lumineuse ne s'affiche pas avec un remplissage vertical ou le placement Depuis le bord gauche"
L["The glow line is not shown on a vertical fill or with the From Right Edge placement"] = "La ligne lumineuse ne s'affiche pas avec un remplissage vertical ou le placement Depuis le bord droit"
L["The glow line is not shown with Absorb Style None"] = "La ligne lumineuse ne s'affiche pas avec le style d'absorption Aucun"
L["The Lich King"] = "Le roi-liche"
L["The native social window with class icons, class-coloured names, faction banners and invite auto-accept; friend actions and every social tab stay native."] = "La fenêtre sociale native avec icônes de classe, noms colorés par classe, bannières de faction et acceptation auto des invitations ; les actions d'amis et tous les onglets sociaux restent natifs."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Les cadres, anneaux et emplacements d'origine là où le jeu les a, avec les fonctionnalités d'EllesmereUI."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Le groupe de remplacement '%s' fournit déjà le Mode Déverrouillage personnalisé de votre spécialisation actuelle. Personnalisez-le là-bas, ou retirez cette spécialisation de ce groupe."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "Le cadre de barre de l'affichage des ressources personnelles, ou le cadre classique de barre d'incantation, sur les barres de vie, de puissance et de ressource de classe, avec toutes les fonctionnalités de barre d'EllesmereUI."
L["The Pixel Glow settings this bar's per-icon glows use. The template never changes them."] = "Les réglages de lueur pixel utilisés par les lueurs par icône de cette barre. Le modèle ne les modifie jamais."
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile est activée."
L["The socketed gem will be destroyed. Continue?"] = "La gemme sertie sera détruite. Continuer ?"
L["The taintLog and scriptProfile CVars are enabled."] = "Les CVars taintLog et scriptProfile sont activées."
L["The taintLog CVar is enabled."] = "La CVar taintLog est activée."
L["The tracker always hides in arenas"] = "Le suivi est toujours masqué en arène"
L["These are the same settings found on each module's own pages, not separate ones."] = "Ce sont les mêmes réglages que sur les pages de chaque module, pas des réglages distincts."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Ces spécialisations ont des valeurs de remplacement qu'aucun mode d'édition de groupe ne peut plus atteindre (laissées par des changements d'appartenance). Elles s'appliquent toujours. Retirez-en une pour rendre à cette spécialisation la valeur par défaut partagée."
L["Thickness in pixels. -1 follows each debuff indicator's Border setting, 0 hides the dispel color border."] = "Épaisseur en pixels. -1 suit le réglage Bordure de chaque indicateur d'affaiblissement, 0 masque la bordure de couleur de dissipation."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Cette action est irréversible. Pensez d'abord à exporter ce profil en sauvegarde."
L["This cannot be undone. Export your own profile as a backup first."] = "Cette action est irréversible. Exportez d'abord votre propre profil en sauvegarde."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Ce contrôle a récemment changé de sens : il copie maintenant DEPUIS le cadre choisi. Confirmer copiera tous les réglages partagés DE %1$s VERS %2$s."
L["This element cannot use group-based visibility."] = "Cet élément ne peut pas utiliser la visibilité basée sur le groupe."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Cet élément s'affiche dès qu'UNE condition Afficher est remplie. Masquer garde son sens dans les deux modes : un Masquer coché masque toujours, sur chaque ligne."
L["This element will only show while you are inside a house or plot"] = "Cet élément ne s'affichera que lorsque vous êtes dans une maison ou un terrain"
L["This element will only show while you are mounted"] = "Cet élément ne s'affichera que lorsque vous êtes sur une monture"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Cet export inclut des réglages inter-profils qui écraseront ceux de l'utilisateur qui l'importe, notamment Confort de jeu, Hovercast et d'autres qui ne devraient généralement pas être partagés avec des profils standard. CECI N'EST PAS RECOMMANDÉ pour le partage public de profils."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Cette fonctionnalité optimise vos réglages graphiques en jeu pour offrir la meilleure combinaison de FPS élevés et de clarté visuelle.\n\nVous pouvez annuler toutes les modifications à tout moment en cliquant sur \"Restaurer mes réglages\", qui apparaîtra après l'optimisation.\n\n\nCe que nous modifions :\n\n"
L["This glow is locked on its settings page."] = "Cette lueur est verrouillée sur sa page de réglages."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Le gestionnaire d'affaiblissements personnalisé de ce groupe ne peut être activé ou modifié qu'en jouant l'une de ses spécialisations."
L["This is a CDM Bar Layout string, not a profile string."] = "Ceci est une chaîne de disposition de barres CDM, pas une chaîne de profil."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "Ceci est une ancienne chaîne de disposition de barres CDM. Ce format n'est plus pris en charge. Utilisez plutôt l'importation de profil standard."
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Cette option ne peut pas être utilisée tant que l'art de ressource de classe Blizzard est activé dans Barres de ressource."
L["This option does not apply to the player frame."] = "Cette option ne s'applique pas au cadre du joueur."
L["This option is not available on the player frame"] = "Cette option n'est pas disponible sur le cadre du joueur"
L["This option only affects Raid Buffs you can cast"] = "Cette option n'affecte que les améliorations de raid que vous pouvez lancer"
L["This option only applies to the Badge style."] = "Cette option ne s'applique qu'au style Badge."
L["This option only applies when Name > Target is selected."] = "Cette option ne s'applique que si Nom > Cible est sélectionné."
L["This option only applies when Name > Target or Target is selected."] = "Cette option ne s'applique que si Nom > Cible ou Cible est sélectionné."
L["This option only applies when Target is selected."] = "Cette option ne s'applique que si Cible est sélectionné."
L["This option only applies when the text shows a name."] = "Cette option ne s'applique que si le texte affiche un nom."
L["This option requires a 2D Portrait or Class Art Style."] = "Cette option nécessite un portrait 2D ou le style graphique Classe."
L["This option requires a Border Size above 0"] = "Cette option nécessite une taille de bordure supérieure à 0"
L["This option requires a Border Style other than Inherit (Main Frames)."] = "Cette option nécessite un style de bordure autre que Hériter (cadres principaux)."
L["This option requires a Border Style other than Solid."] = "Cette option nécessite un style de bordure autre que Uni."
L["This option requires a border style with divider art and a Border Size above 0."] = "Cette option nécessite un style de bordure avec séparateurs et une taille de bordure supérieure à 0."
L["This option requires a Circle or Pixels Circle Shape."] = "Cette option nécessite une forme Cercle ou Cercle pixels."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Cette option nécessite Superposition de dissipation, Colorer les bordures perso ou Utiliser les couleurs de dissipation."
L["This option requires a Glow Style other than None"] = "Cette option nécessite un style de lueur autre que Aucun"
L["This option requires a Type Icon Position other than None"] = "Cette option nécessite une position d'icône de type autre que Aucune"
L["This option requires a visible Portrait and Show Icon."] = "Cette option nécessite un portrait visible et Afficher l'icône."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Cette option nécessite une barre de puissance attachée, une taille de bordure supérieure à 0 et un style de bordure avec jointure."
L["This option requires an EllesmereUI Target or Focus frame."] = "Cette option nécessite un cadre de cible ou de focalisation EllesmereUI."
L["This option requires an Outer Ring other than None."] = "Cette option nécessite un anneau extérieur autre que Aucun."
L["This option requires Art Style to be set to Class"] = "Cette option nécessite le style graphique Classe"
L["This option requires Blizzard Style to be disabled"] = "Cette option nécessite que le style Blizzard soit désactivé"
L["This option requires Combine Spell Name and Target to be disabled."] = "Cette option nécessite que Combiner nom du sort et cible soit désactivé."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Cette option nécessite un style de bordure perso, Afficher l'icône et Intégrer l'icône à la barre, avec le style EllesmereUI."
L["This option requires Dispel Type Borders to be enabled."] = "Cette option nécessite que les bordures de type de dissipation soient activées."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Cette option nécessite Afficher l'icône et Intégrer l'icône à la barre, avec le style EllesmereUI."
L["This option requires Show Icon and the EllesmereUI style."] = "Cette option nécessite Afficher l'icône et le style EllesmereUI."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Cette option nécessite Afficher l'icône à côté de la barre d'incantation et le style EllesmereUI."
L["This option requires Show Level."] = "Cette option nécessite Afficher le niveau."
L["This option requires Solid or a border style with divider art, and a Border Size above 0."] = "Cette option nécessite Uni ou un style de bordure avec séparateurs, et une taille de bordure supérieure à 0."
L["This option requires the Class Art Style."] = "Cette option nécessite le style graphique Classe."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Cette option nécessite la bordure de forme colorée par classe et le mode sombre."
L["This option requires the WoW Forever style."] = "Cette option nécessite le style WoW Forever."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Ceci écrase les réglages actuels de ce cadre. La position, la visibilité et l'activation du cadre ne sont pas modifiées."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Ceci écrase définitivement les réglages de ce profil avec le remplacement '%s' : ses réglages capturés et ses dispositions personnalisées du Mode Déverrouillage et du gestionnaire d'améliorations (le cas échéant) deviennent la base du profil pour chaque spécialisation. TOUS les groupes de remplacement de spécialisation de ce profil sont ensuite supprimés et l'UI est rechargée. Les remplacements conditionnels ne sont pas affectés."
L["This profile string does not carry any global settings."] = "Cette chaîne de profil ne contient aucun réglage global."
L["This profile string does not carry any override data."] = "Cette chaîne de profil ne contient aucune donnée de remplacement."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Cette chaîne de profil ne contient aucun réglage d'habillage des fenêtres et infobulles."
L["This profile was created before the beta wipe and is no longer compatible. Please create a new export."] = "Ce profil a été créé avant la réinitialisation de la bêta et n'est plus compatible. Veuillez créer un nouvel export."
L["This profile was created with a newer version of EllesmereUI. Please update your addon."] = "Ce profil a été créé avec une version plus récente d'EllesmereUI. Veuillez mettre à jour votre addon."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Ce profil a été créé avec une échelle d'UI de %1$d%% ; la vôtre est de %2$d%%. Changer votre échelle d'UI pour correspondre au profil importé ? Tous les profils s'afficheront à cette échelle car l'échelle d'UI n'est pas un réglage par profil, mais vous pouvez revenir à votre valeur d'origine à tout moment."
L["This Setting Has Overrides"] = "Ce réglage a des remplacements"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "Le Mode Déverrouillage personnalisé de cette spécialisation appartient à '%s'. Personnalisez-le là-bas, ou retirez la spécialisation de ce groupe."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Cette chaîne est un export de COMPTE COMPLET. Elle remplace vos réglages de compte par ceux de l'expéditeur, y compris Confort de jeu, les raccourcis HoverCast, les configurations de sorts du gestionnaire de recharge, les ancrages déverrouillés, l'échelle d'UI et les raccourcis de profil -- pas seulement un profil. Vos autres profils sont conservés, mais un profil portant le même nom est remplacé."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Ceci crée un gestionnaire d'améliorations entièrement unique pour ce groupe conditionnel. Les modifications de votre gestionnaire d'améliorations par défaut ne l'affecteront plus."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Ceci crée un gestionnaire d'améliorations entièrement unique pour ce groupe de remplacement. Les modifications de votre gestionnaire d'améliorations par défaut n'affecteront plus ces spécialisations."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Ceci crée un gestionnaire d'affaiblissements entièrement unique pour ce groupe conditionnel. Vos réglages actuels du gestionnaire d'affaiblissements servent de point de départ, et les modifications de votre gestionnaire par défaut ne l'affecteront plus."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Ceci crée un gestionnaire d'affaiblissements entièrement unique pour ce groupe de remplacement. Vos réglages actuels du gestionnaire d'affaiblissements servent de point de départ, et les modifications de votre gestionnaire par défaut n'affecteront plus ces spécialisations."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Ceci remplacera VOS réglages Blizz UI Enhanced (les onglets Habillage des fenêtres et Infobulles, menus et fenêtres) par ceux de l'expéditeur, sur TOUS vos profils. Vos réglages actuels de ces deux onglets ne pourront pas être récupérés ensuite."
