L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Ce qui se trouve devant le nombre. Icône affiche l'icône du personnage ; les nuances de couleur à gauche la teintent."
L["When Healing uses your role or healing talents"] = "Quand Soins utilise votre rôle ou vos talents de soins"
L["When on, flask/food/weapon/poison reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Si activé, les rappels de flacon/nourriture/arme/poison s'affichent quand même (atténués) si vous n'avez pas l'objet correspondant dans vos sacs, pour vous inciter à vous réapprovisionner.\nSi désactivé, ils sont entièrement masqués si vous ne portez pas l'objet."
L["When unlocked, hold Shift and drag the minimap. Position is also available in Unlock Mode."] = "Une fois déverrouillée, maintenez Shift et faites glisser la minicarte. La position est aussi disponible dans le Mode Déverrouillage."
L["Where to Show"] = "Où afficher"
L["Which audio channel the block's volume bar adjusts."] = "Le canal audio que règle la barre de volume du bloc."
L["Which latency to show: home, world, or both side by side."] = "Latence à afficher : domicile, monde, ou les deux côte à côte."
L["Which part of the row stays in place as reminders appear and disappear."] = "La partie de la rangée qui reste en place quand les rappels apparaissent et disparaissent."
