L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r Toutes les astuces réinitialisées. Faites /reload pour les revoir."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r Échelle d'UI réinitialisée. Faites /reload pour la reprendre depuis votre échelle Blizzard."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r Introduction des remplacements réinitialisée. La fenêtre d'annonce s'affichera à votre prochain /reload ; le guide vidéo à votre prochain clic sur le glyphe des remplacements."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r Guides vidéo et astuces réinitialisés. Les badges sont de retour ; les fenêtres uniques s'afficheront à nouveau."
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r Impossible d'entrer en Mode Déverrouillage en combat."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r Impossible d'ouvrir les options en combat. Utilisez /eui pour voir les notes de mise à jour."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r Spécialisation changée : Mode Déverrouillage fermé, modifications de disposition non enregistrées abandonnées."
