L["A friendly focus wins over the tank. The focus is checked at the moment you press it, also in combat."] = "Une focalisation amicale passe avant le tank. La focalisation est vérifiée au moment où vous appuyez, y compris en combat."
L["A group member to use as the tank. Empty uses the raid Main Tank, then the Dungeon Finder tank role. Updates out of combat."] = "Un membre du groupe à utiliser comme tank. Vide utilise le tank principal du raid, puis le rôle de tank de l'Outil Donjons. Mis à jour hors combat."
L["A line at every 10% and a tick at every 5% across the bar."] = "Une ligne tous les 10 % et un repère tous les 5 % le long de la barre."
L["A raid control panel with ready check, pull timer and target markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un panneau de contrôle du raid avec appel, compte à rebours de pull et marqueurs de cible. En raid, il ne s'affiche que si vous êtes chef ou assistant, car aucun de ses boutons ne fonctionne sans cela ; en groupe, il s'affiche toujours."
