L["Hide Until Usable: only shown while usable and off cooldown, such as Overpower or Victory Rush after a proc; low resources do not hide it. Hide Outside Form/Stance: only shown in the form or stance the spell needs, even on cooldown. Keep Place leaves the gap; the others close it."] = "Masquer jusqu'à utilisable : affiché seulement s'il est utilisable et hors recharge, comme Fulgurance ou Ivresse de la victoire après un effet déclenché ; le manque de ressources ne le masque pas. Masquer hors forme/posture : affiché seulement dans la forme ou posture requise par le sort, même en recharge. Garder la place laisse l'espace ; les autres le referment."
L["Hides the Bloodlust and Heroism lockout debuffs."] = "Masque les affaiblissements de blocage de Furie sanguinaire et Héroïsme."
L["Highlight Items on Stat Hover"] = "Surligner les objets au survol des stats"
L["Hovering a stat in the sidebar glows the equipped items that give it (Hit, Crit, Haste, Defense, Strength...)."] = "Survoler une stat dans la barre latérale fait briller les objets équipés qui la donnent (Toucher, Critique, Hâte, Défense, Force...)."
L["Hunters and Rogues: an icon you click (or bind in Key Bindings > EllesmereUI Quality of Life) that casts Misdirection or Tricks of the Trade on your focus, else the tank, else a friendly target"] = "Chasseurs et voleurs : une icône à cliquer (ou à lier dans Raccourcis > EllesmereUI Confort de jeu) qui lance Détournement ou Ficelles du métier sur votre focalisation, sinon le tank, sinon une cible amicale"
L["Ignore Low Level Quests"] = "Ignorer les quêtes de bas niveau"
L["Import Into Active Profile?"] = "Importer dans le profil actif ?"
L["Import into current profile (%1$s)"] = "Importer dans le profil actuel (%1$s)"
L["Import Into Your Current Profile"] = "Importer dans votre profil actuel"
L["Import Retail Profiles"] = "Importer des profils Retail"
L["In Any Group"] = "Dans n'importe quel groupe"
L["Incomplete quests"] = "Quêtes inachevées"
L["Inspect Enchant Name Size"] = "Taille du nom d'enchantement à l'inspection"
L["Inspect Missing Enchant, Gem & Buckle Icons"] = "Icônes d'enchantement, de gemme et de boucle manquants à l'inspection"
L["Invert Scroll Wheel"] = "Inverser la molette"
L["Item ID on Tooltip"] = "ID d'objet dans l'infobulle"
L["Junk Marker"] = "Marqueur de camelote"
L["Junk Marker Options"] = "Options du marqueur de camelote"
L["Just the micro menu buttons."] = "Seulement les boutons du micro-menu."
L["Keep Session on Reload"] = "Garder la session au rechargement"
L["Keeps the bar at max level, full, with the level and times. Time This Level shows total time played there."] = "Garde la barre au niveau maximum, pleine, avec le niveau et les temps. Temps à ce niveau affiche le temps de jeu total à ce niveau."
L["Left Endcap"] = "Embout gauche"
L["Left Endcap or Right Endcap"] = "Embout gauche ou embout droit"
L["Macro alternative: /click EUI335QoLRedirect"] = "Alternative en macro : /click EUI335QoLRedirect"
L["Menu Grow Direction"] = "Direction d'ouverture du menu"
L["MISDIRECTION / TRICKS HELPER"] = "AIDE DÉTOURNEMENT / FICELLES"
L["Misdirection / Tricks Helper"] = "Aide Détournement / Ficelles"
L["Misses, Dodges and Parries"] = "Échecs, esquives et parades"
L["Module Default follows the Raid Frames font outline from the Fonts page."] = "Défaut du module suit le contour de police des cadres de raid de la page Polices."
L["Name Outline"] = "Contour du nom"
L["Native"] = "Natif"
L["Native: the client's dark square sweep. Shaped: a drawn sweep that follows round icons and takes the Swipe Color."] = "Natif : le balayage carré sombre du client. Façonné : un balayage dessiné qui suit les icônes rondes et prend la couleur de balayage."
L["Nest Distance"] = "Distance d'imbrication"
L["Nest Distance and Size"] = "Distance et taille d'imbrication"
L["Nest Icon Size"] = "Taille des icônes imbriquées"
L["No DataBars"] = "Aucune DataBar"
L["One Window"] = "Une fenêtre"
L["Only Dispellable"] = "Dissipables uniquement"
L["Only Group & Pull"] = "Groupe et pull uniquement"
L["Only Markers"] = "Marqueurs uniquement"
L["Own and Raid Debuffs"] = "Affaiblissements personnels et de raid"
L["Own Keybind"] = "Raccourci propre"
L["Percent of the end caps' normal size."] = "Pourcentage de la taille normale des embouts."
L["Picks an NPC's only dialog option for you."] = "Choisit pour vous l'unique option de dialogue d'un PNJ."
L["Player Buffs on Tooltips"] = "Améliorations du joueur dans les infobulles"
L["Positive values move both end caps away from the bar."] = "Les valeurs positives éloignent les deux embouts de la barre."
L["Primary Spec"] = "Spécialisation principale"
L["PULL TIMER"] = "COMPTE À REBOURS DE PULL"
L["Pushes older messages along so a new one never overlaps them."] = "Pousse les anciens messages pour qu'un nouveau ne les chevauche jamais."
L["Quest XP Overlay"] = "Superposition de l'EXP de quête"
L["Raid Debuffs Filter"] = "Filtre des affaiblissements de raid"
L["Raid Debuffs shows the common raid debuffs (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements, Hunter's Mark) from anyone."] = "Affaiblissements de raid affiche les affaiblissements de raid courants (armure, dégâts des sorts et physiques subis, critiques subis, puissance d'attaque, vitesse d'attaque et d'incantation, soins reçus, Jugements, Marque du chasseur) de n'importe qui."
L["Reads the item's own stats; enchants and gems are not counted."] = "Lit les caractéristiques propres de l'objet ; les enchantements et gemmes ne sont pas comptés."
L["Reload to finish resetting EUI."] = "Rechargez pour terminer la réinitialisation d'EUI."
L["Reload to finish uninstalling EUI."] = "Rechargez pour terminer la désinstallation d'EUI."
L["Rename DataBar"] = "Renommer la DataBar"
L["Rested After Quest XP"] = "Repos après l'EXP de quête"
L["Rested color"] = "Couleur de repos"
L["Return every EUI addon to its defaults."] = "Remet chaque addon EUI à ses valeurs par défaut."
L["Revert EUI's changes and disable."] = "Annule les modifications d'EUI et le désactive."
L["Right Endcap"] = "Embout droit"
L["Scroll Distance"] = "Distance de défilement"
L["Second Timer"] = "Deuxième compte à rebours"
L["Secondary Spec"] = "Spécialisation secondaire"
L["Selection Color"] = "Couleur de sélection"
L["Selection Color: Custom Color"] = "Couleur de sélection : couleur personnalisée"
L["SELF COMBAT TEXT"] = "TEXTE DE COMBAT PERSONNEL"
L["Self Combat Text"] = "Texte de combat personnel"
L["Sell Junk skips items with no vendor price, equipment set gear and pinned items."] = "Vendre la camelote ignore les objets sans prix de vente, les objets d'ensembles d'équipement et les objets épinglés."
L["Shaped"] = "Façonné"
L["Shaped Cooldown Swipe"] = "Balayage de recharge façonné"
L["Share Keybind With"] = "Partager le raccourci avec"
L["Shift + Click World Markers"] = "Maj + Clic sur les marqueurs au sol"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "Maj + Clic gauche sur une icône de marqueur utilise son objet de marqueur au sol, puis cliquez au sol. Seuls les marqueurs dont l'objet est dans vos sacs en profitent ; les autres gardent Maj + Clic pour effacer le marqueur de cible. Maj + Clic gauche sur l'icône d'effacement appuie sur le bouton Réinitialiser les marqueurs du serveur."
L["Show a small coin in the corner of items marked as junk."] = "Affiche une petite pièce dans le coin des objets marqués comme camelote."
L["Show as"] = "Afficher comme"
L["Show at Max Level"] = "Afficher au niveau maximum"
L["Show Coin on Junk"] = "Afficher une pièce sur la camelote"
L["Show Convert to Raid"] = "Afficher Convertir en raid"
L["Show Disband"] = "Afficher Dissoudre"
L["Show Dividers"] = "Afficher les séparateurs"
L["Show Equipped Item Color"] = "Afficher la couleur des objets équipés"
L["Show Inspect Enchant Names Instead of Icons"] = "Afficher les noms d'enchantement à l'inspection au lieu des icônes"
L["Show Item Icon Name"] = "Afficher le nom de l'icône d'objet"
L["Show Item ID on Tooltip"] = "Afficher l'ID d'objet dans l'infobulle"
L["Show Player Buffs"] = "Afficher les améliorations du joueur"
L["Show Reinvite"] = "Afficher Réinviter"
L["Show Rested XP"] = "Afficher l'EXP de repos"
L["Show Target Name"] = "Afficher le nom de la cible"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "Affiche le bouton pièce dans l'en-tête du sac. Cliquez dessus, puis cliquez sur des objets pour les marquer ou démarquer comme camelote. La camelote va dans sa propre catégorie Camelote, et un bouton Vendre la camelote apparaît à côté de la pièce quand un marchand est ouvert."
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "Affiché au niveau maximum. Les bonus de métier ne sont vérifiés que sur votre propre fiche."
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "Affiche les affaiblissements de raid courants de n'importe qui : armure, dégâts des sorts et physiques subis, critiques subis, puissance d'attaque, vitesse d'attaque et d'incantation, soins reçus, Jugements et Marque du chasseur."
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "Affiche le bouton Convertir en raid. Dans un raid de cinq joueurs ou moins, il indique Convertir en groupe : tout le monde est retiré puis réinvité dans un nouveau groupe."
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "Affiche les affaiblissements que vous appliquez plus les affaiblissements de raid courants de n'importe qui."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Affiche le bouton Dissoudre. Il demande toujours confirmation avant de dissoudre, mais le masquer le met définitivement hors de portée des clics accidentels."
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "Affiche les améliorations du joueur survolé sous forme d'icônes à côté de l'infobulle (jusqu'à 16)."
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "Affiche la superposition, l'icône de type et les couleurs de bordure uniquement pour les affaiblissements que vous pouvez dissiper actuellement."
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "Affiche le bouton Réinviter. Il demande d'abord, puis retire tout le monde et le réinvite dans le même type de groupe. Les joueurs doivent accepter la nouvelle invitation."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "Affiche vos dégâts subis, soins, évitements et entrées/sorties de combat au-dessus du cadre du joueur au lieu du texte de combat de Blizzard, dont les autres messages sont masqués tant que ceci est actif. Déplacez-le en mode Déverrouillage."
L["Smart Ticks"] = "Repères intelligents"
L["Spell IDs in the Breakdown"] = "ID des sorts dans le détail"
L["Stagger Hits"] = "Échelonner les messages"
L["Stat Hover Highlight"] = "Surbrillance au survol des stats"
L["Static"] = "Statique"
L["Straight"] = "Droit"
L["Style Page Look Menus"] = "Menus d'apparence de la page Style"
L["Swipe Color"] = "Couleur de balayage"
L["Swipe Style"] = "Style de balayage"
L["Tank Name"] = "Nom du tank"
L["Text Shadow"] = "Ombre du texte"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "La WeakAura Barre d'expérience [Merfin] (Luxthos) : dégradé bleu à violet, superposition de l'EXP de quête, étincelle, repos après l'EXP de quête et sept textes avec niveau, temps et temps avant le niveau suivant."
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "Le cadre d'infobulle classique autour de la fenêtre du compteur, avec les boutons d'en-tête d'origine et toutes les fonctions de compteur d'EllesmereUI."
L["The gap between a nested menu's icons and the entry that opens it."] = "L'écart entre les icônes d'un menu imbriqué et l'entrée qui l'ouvre."
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "Le segment de repos commence là où finit la superposition de l'EXP de quête au lieu de votre EXP actuelle."
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "Le groupe de talents dans lequel ce menu d'actions fonctionne. En dehors, le raccourci ne fait rien et le menu est masqué là où il est imbriqué."
L["Third Timer"] = "Troisième compte à rebours"
L["This option requires an EllesmereUI Focus frame."] = "Cette option nécessite un cadre de focalisation EllesmereUI."
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "Cette option nécessite le style de barre d'EXP EllesmereUI ou Luxthos"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "Temps de cette session et EXP par heure continuent après un /reload (un chargement dans les cinq minutes) au lieu de repartir de zéro."
L["Timed Buffs"] = "Améliorations temporaires"
L["Toggle Raid Tools"] = "Afficher/masquer les outils raid"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Affiche ou masque les panneaux des outils raid, en combat ou hors combat.\n\nClic gauche pour définir un raccourci.\nClic droit pour le supprimer."
L["Two Windows"] = "Deux fenêtres"
L["Uninstall & Reload"] = "Désinstaller et recharger"
L["Uninstall EUI"] = "Désinstaller EUI"
L["Up Left"] = "Haut gauche"
L["Up Right"] = "Haut droite"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "Utilise le raccourci d'un autre menu d'actions tant que ce menu n'est pas chargé. Les deux menus doivent être assignés à des spés différentes."
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "Les améliorations affichées par les barres d'info ennemies. Affinez ce réglage dans la page Filtres d'aura."
L["Which ends of the bar show the gryphons."] = "Les extrémités de la barre qui affichent les griffons."
L["XP Bar Style"] = "Style de barre d'EXP"
L["XP color"] = "Couleur d'EXP"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "Chaque module fonctionne avec les API natives de Wrath. Les apparences et réglages Retail ont été portés partout où le client 3.3.5a les prend en charge, et les systèmes propres à Retail ont été laissés de côté. Les notes sont regroupées par module, des plus récentes aux plus anciennes, et chaque en-tête indique la version du portage de ce module."
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "Des icônes à côté de chaque ennemi pour chaque catégorie de contrôle de foule qu'il subit ou dont il se remet : vert signifie que le prochain durera moitié moins, jaune un quart, rouge immunisé. Un chrono affiche la réinitialisation de 18 secondes."
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "Une barre de vie pour chaque familier ennemi sous le cadre de son maître. Le clic gauche cible le familier, le clic droit le met en focalisation."
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "Cadres ennemis pour arena1-5 avec barres de vie aux couleurs de classe, de ressource et d'incantation, plus une surbrillance sur votre cible. Le clic gauche cible, le clic droit met en focalisation. Il n'y a pas d'équivalent Retail."
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "L'icône de classe est remplacée par le contrôle de foule ou l'immunité de plus haute priorité avec une spirale et un chrono, et l'icône du bijou JcJ suit sa recharge de 2 minutes depuis le journal de combat."
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "Texture de barre liste les textures de SharedMedia et d'autres addons utilisant LibSharedMedia"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "Les ennemis au-delà de la portée de sorts de 30-40 mètres de votre classe s'estompent jusqu'à l'opacité choisie"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "Aperçu de 2 à 5 cadres d'exemple en mode Déverrouillage, tant que la page d'options est ouverte, ou avec /earena test"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "Les cadres restent affichés quand un ennemi est camouflé ou hors de vue, atténués et marqués Invisible"
L["Optionally hides Blizzard's arena frames while these are in use"] = "Masque éventuellement les cadres d'arène de Blizzard tant que ceux-ci sont utilisés"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "Le Filtre des affaiblissements reçoit Affaiblissements de raid et Affaiblissements personnels et de raid, avec la même liste d'affaiblissements de raid que les cadres d'unité."
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "Choisissez les améliorations affichées par les barres d'info ennemies : Améliorations temporaires, Dissipables uniquement ou Tout afficher, qui affiche toutes les améliorations."
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "Chaque texte des barres d'info a un choix de contour sous sa Taille : Aucun, Contour, Contour épais ou Ombre, ou garder la valeur par défaut du module. Concerne les noms, le niveau, la vie, la cible de la cible, les textes d'incantation, le texte des auras et les noms amicaux."
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "Les barres d'incantation se remplissent maintenant à chaque image au lieu d'avancer par à-coups à chaque rafraîchissement des barres d'info. L'étincelle et le chrono bougent aussi en douceur, et le travail supplémentaire s'arrête quand aucune incantation n'est visible."
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "Positions du texte principal propose tous les textes Retail : Nom de l'ennemi, Niveau | Nom, Cible de la cible, Vie % et Vie # avec leurs variantes combinées. La roue dentée de chaque texte règle sa taille."
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "Les barres de vie et d'incantation proposent les textures EllesmereUI (Melli, Atrocity, Fade, Matte et plus), comme sur Retail"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "Les textures des barres de vie et d'incantation incluent celles de SharedMedia et d'autres addons"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "Affichage et Couleurs montrent une barre d'info d'aperçu en direct ; cliquez sur n'importe quelle partie pour aller à son réglage"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "Taille de barre, couleurs, modes de menace, couleurs d'incantation, flèches de cible et Lueur pulsée d'exécution de Retail"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "Chaque emplacement contient un élément ; les auras, le marqueur de raid et la classification peuvent aussi se placer sous la barre d'incantation"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "Vie # utilise les abréviations style Blizzard (1.2K, 12K, 1.2M) avec une décimale de % optionnelle"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "Un profil importé depuis Retail ne fait plus gonfler la barre d'info de la cible jusqu'à remplir l'écran."
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "Bordure Aucune masque maintenant uniquement les bordures, pas le texte, le chrono, le bouclier ni la marque d'interruption de la barre d'incantation."
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "La barre d'info d'aperçu des options ne disparaît plus après un changement d'onglet ou la fermeture du panneau."
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "La couleur d'incantation Interruption en recharge s'affiche maintenant pendant la recharge de votre interruption, comme sur Retail, et non l'inverse."
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "Les noms de raid et de groupe ont chacun leur propre contour : Aucun, Contour, Contour épais, Ombre, ou la police par défaut des cadres de raid."
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "Une nouvelle Disposition du groupe empile deux groupes de raid par colonne, puis commence la colonne suivante à droite, de sorte qu'un raid de 20 joueurs forme un bloc 2x2."
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "Les icônes d'appel apparaissent au-dessus des affaiblissements et conservent le résultat de chaque joueur pendant dix secondes après la fin de l'appel."
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "L'affaiblissement affiché dans l'icône centrale d'affaiblissement de raid est exclu de la barre d'affaiblissements normale, laissant de la place aux autres."
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "Les cadres de raid et de groupe s'atténuent hors de portée sur Wrath, y compris en combat. Atténuer hors de portée et Alpha hors de portée contrôlent l'estompage."
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "Une grande icône au milieu de chaque cadre pour les affaiblissements importants de la Citadelle de la Couronne de glace, du Sanctum rubis, de l'épreuve du croisé, d'Ulduar et de Naxxramas, par ordre de priorité, avec chrono, cumuls et une bordure à la couleur de dissipation. Sans affaiblissement listé, elle peut afficher à la place un affaiblissement dissipable."
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "Styles de Superposition de dissipation avec opacité, une Bordure du cadre à la couleur de dissipation, Position de l'icône de type, Couleurs de dissipation par type et Afficher uniquement les dissipables."
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "Superposition, Réel ou Pas d'aperçu. L'aperçu s'ouvre quand la page Raid ou Groupe est ouverte et se ferme quand vous la quittez, fermez le panneau ou entrez en combat."
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "Les incantations ennemies s'affichent en icônes sur le membre du groupe ou du raid visé, avec un balayage d'incantation et une bordure interruptible. Le groupe utilise En soin par défaut ; chaque disposition de raid a son propre mode. Wrath n'a pas de cible de sort, donc la victime est la cible du lanceur, et seuls les ennemis ciblés par quelqu'un du groupe sont vus"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "Les boucliers de dégâts s'affichent sur la barre de vie comme sur Retail : Style d'absorption, Opacité, Couleur, Placement et Afficher le sur-bouclier. Wrath ne communique pas la valeur des boucliers, elle est donc estimée à partir du journal de combat"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "Texture de la barre de vie liste les textures de SharedMedia et d'autres addons, y compris dans l'aperçu des indicateurs d'aura"
L["25-Player Preview"] = "Aperçu à 25 joueurs"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "Les aperçus du mode Déverrouillage et des options s'ouvrent sur la disposition à 25 joueurs au lieu de 40"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "Modes de couleur de vie, fonds, menace, bordures de cible et de survol, placement des textes et des icônes"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "Soins entrants et résurrections des joueurs qui utilisent un addon HealComm"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "Cadres de tank principal, de familier et de boss amical plus le texte de mana des soigneurs, chacun avec son déplaceur en mode Déverrouillage"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "La page Groupe a une section DISPOSITION avec Cadres horizontaux"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "Les icônes d'appel affichent une coche verte pour les joueurs qui ont accepté et pour celui qui a lancé l'appel, au lieu d'un X rouge à la fin de l'appel."
L["The party leader icon shows on the leader only instead of on several party members."] = "L'icône de chef de groupe s'affiche uniquement sur le chef au lieu de plusieurs membres du groupe."
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "Définir la focalisation et Effacer la focalisation dans le menu des cadres de raid et de groupe fonctionnent hors combat sans la fenêtre « bloqué pour une action » ; en combat ils sont masqués, utilisez-y un raccourci de focalisation d'Incantation au clic."
L["Ready check icons show on raid and party frames again."] = "Les icônes d'appel s'affichent de nouveau sur les cadres de raid et de groupe."
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "Masquer Rassasié / Épuisement masque aussi l'affaiblissement de blocage de Furie sanguinaire 81005."
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "Les cadres de familier ne provoquent plus d'erreur strupper de SecureTemplates à leur première apparition."
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "Le menu Ajouter de l'éditeur Améliorations/Affaiblissements ne se ferme plus au premier clic."
L["Element Options for raid and party frames now open the matching settings."] = "Options de l'élément des cadres de raid et de groupe ouvrent maintenant les réglages correspondants."
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "Les chaînes de profil exportées depuis EllesmereUI Retail importent tout ce que ce client prend en charge : chaque module conserve ses réglages actuels et prend les valeurs Retail qu'il comprend. Les modules propres à Retail, les configurations de spé et les sorts du Gestionnaire de recharge sont ignorés, et la discussion indique combien de réglages ont été importés."
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "Un bouton dans Réglages globaux rétablit les réglages du jeu modifiés par EUI (options des barres d'info, de la minicarte, de la discussion et des infobulles, tailles de police de la discussion et touches prises par Quickdraw), puis désactive EUI pour ce personnage et recharge. Vos profils sont conservés."
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "Un balayage de recharge dessiné pour les modules qui veulent des balayages ronds ou colorés ; le balayage propre au client Wrath est toujours un carré sombre. Le Gestionnaire de recharge l'utilise en premier."
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "Quand un membre de la guilde ou du groupe utilise une version plus récente d'EllesmereUI, la discussion vous en informe une fois par session. Tapez /euiupdate pour le lien de téléchargement. Wrath n'a pas d'accès à Internet, l'information vient donc des autres utilisateurs d'EUI."
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "L'addon Locales fournit des traductions communautaires pour toutes les langues d'origine du client Wrath, avec repli sur l'anglais et formatage Lua 5.1."
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "Le menu replié affiche le logo E d'origine d'Ellesmere avec la couleur d'accent de l'interface et une icône de fermeture fonctionnelle sur le client Wrath."
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "Les polices, textures de barre et sons que d'autres addons enregistrent auprès de LibSharedMedia apparaissent dans les menus d'EllesmereUI, y compris ceux enregistrés après la connexion."
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "Un sélecteur de contour partagé pour chaque texte : Aucun, Contour, Contour épais ou Ombre, avec Défaut du module qui suit la page Polices. Le texte garde sa couleur quand vous changez."
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "La fenêtre d'addon incompatible peut désactiver l'autre addon ou le module EllesmereUI concerné et recharger. Okay et Ne plus afficher fonctionnent comme avant."
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "Groupes de réglages par spé avec capture automatique et leurs propres dispositions du mode Déverrouillage, plus des remplacements conditionnels pour les donjons, raids, arènes, champs de bataille, le jeu en solo et hors combat."
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "Le menu Échap a des boutons EllesmereUI et Mode Déverrouillage EUI, affichés par défaut. Les deux suivent le réglage Boutons EUI dans Réglages globaux."
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "Avec Afficher l'ID du sort dans l'infobulle activé, les infobulles d'objet ajoutent l'ID de l'objet et le nom du fichier d'icône. Chaque ligne a sa propre option"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "Les cadres de raid et d'unité lisent les boucliers d'absorption depuis une estimation partagée : valeur de base du rang plus votre propre puissance des sorts, moins ce que chaque bouclier absorbe dans le journal de combat. Les clients disposant d'une API d'absorption native l'utilisent directement"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "Cadres d'arène rejoint la barre latérale, la liste de première utilisation, les profils, les remplacements par spé, les polices de module et la recherche"
L["Profile strings and shared exports work again"] = "Les chaînes de profil et les exports partagés fonctionnent de nouveau"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "Un thème d'options bleu glacier ; Accent assorti au thème suit la palette de chaque thème"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "Lumières, faisceaux, musique et rotation lors des victoires sur les boss, en arène et en champ de bataille, de Furie sanguinaire/Héroïsme et des montées de niveau"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "Afficher l'ID du sort dans l'infobulle couvre les sorts, les boutons d'action, les auras et les liens de discussion (désactivé par défaut)"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "La barre latérale des options affiche la mémoire totale utilisée par tous les addons EllesmereUI chargés"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "Le bouton de synchronisation de la barre latérale ouvre de nouveau sa liste de profils au lieu de provoquer une erreur quand vous avez plus d'un profil."
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "Les chaînes de profil Retail apportent les positions de leurs éléments : barres d'action, d'EXP et de menu, barres CDM, cadres de raid et de groupe, discussion, fenêtres du compteur de dégâts, affichages QoL, barres de ressources et l'infobulle fixe se placent là où le créateur les a mis."
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "Les chaînes de profil Retail ne contenant que les barres d'info sont reconnues comme Retail ; la largeur et la hauteur des barres, la hauteur et la couleur de la barre d'incantation, la taille des noms et des auras sont reprises."
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "Mode Déverrouillage : les icônes et libellés de bascule de la barre supérieure sont plus lumineux, ils n'apparaissent plus gris foncé sur la bannière."
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "Définir la focalisation et Effacer la focalisation dans les menus du clic droit des cadres EUI passent par un bouton sécurisé hors combat au lieu d'être bloqués ; en combat ils sont masqués."
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "Mode Déverrouillage : les touches fléchées déplacent de nouveau l'élément sélectionné de 1 pixel (maintenez Maj pour 100)."
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "Fonctionne avec !!!ClassicAPI : ses fonctions de découpage et de masque ne sont plus utilisées sur les cadres EUI, donc les lueurs animées et le panneau d'options ne provoquent plus d'erreur."
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "L'ouverture des options ne provoque plus l'erreur \"attempt to index local 'mask'\" sur les clients où un autre addon ajoute une fonction de masque vide."
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "Les zones d'importation et d'exportation de profil ne provoquent plus l'erreur \"attempt to call method 'GetNumLines'\" et défilent pour afficher les longues chaînes."
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "Le menu replié affiche de nouveau le logo E d'Ellesmere au lieu d'un simple cercle noir."
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "Les infobulles des boutons d'action affichent le véritable ID du sort au lieu de l'emplacement du grimoire."
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "Correction d'une erreur \"attempt to call global 'issecretvalue'\" des lueurs du Gestionnaire de recharge avant la première ouverture du panneau d'options."
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "Les infobulles des widgets du mode Déverrouillage utilisent des fondus d'alpha compatibles Wrath, ce qui corrige l'erreur SetFromAlpha sur Croître vers la droite."
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "La liste des résultats de recherche des options a un fond totalement opaque avec ses résultats dessinés par-dessus, le texte de la barre latérale et de la page ne transparaît donc plus dans les résultats."
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "Le mode Déverrouillage ne provoque plus d'erreur SetMaxLines à sa première ouverture, les déplaceurs d'éléments réapparaissent donc."
L["The Patch Notes reminder dot now lights after each backport update."] = "Le point de rappel des notes de patch s'allume maintenant après chaque mise à jour du portage."
L["The options search results now draw above the sidebar and page instead of behind them."] = "Les résultats de recherche des options s'affichent maintenant au-dessus de la barre latérale et de la page au lieu de derrière."
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "Le menu du clic droit du mode Déverrouillage ne se ferme plus juste après son ouverture quand de nombreux éléments sont à l'écran."
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "L'ouverture des options des cadres de raid ne provoque plus de débordement de pile dans Remplacements de réglages."
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "Les illustrations du mode Déverrouillage, les icônes des pages d'options et la barre supérieure du mode Déverrouillage sont maintenant visibles et lisibles."
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "La liste des addons affiche des noms de modules propres, regroupés sous EllesmereUI dans les gestionnaires d'addons."
L["Search Features and Search Module Settings accept typing again."] = "Rechercher des fonctions et Rechercher dans les réglages acceptent de nouveau la saisie."
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "Les clients dont la recherche d'atlas provoque une erreur sur les noms inconnus (comme les clients 3.3.5 personnalisés avec des portages d'interface Retail) n'empêchent plus le chargement des fichiers d'EllesmereUI."
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "Comme sur Retail 9.4, la page DataBars s'ouvre avec un sélecteur de barre en haut : renommez ou supprimez une barre directement dans son menu, ou choisissez + Créer une nouvelle DataBar. + Nouvelle barre affiche les quatre modèles de départ sous forme de cartes, et sans barre la page les affiche en grille de cartes."
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "Comme sur Retail 9.4, la fenêtre d'options a un curseur Échelle de la fenêtre dans son coin supérieur qui la redimensionne par paliers fluides de 5 % ; la molette dessus, ou Maj + molette n'importe où sur la fenêtre, fonctionne aussi. Le crédit à Ellesmere se trouve maintenant sous le bouton de fermeture."
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "Réglages globaux s'ouvre avec Réinitialiser TOUS les réglages des addons EUI et Désinstaller EUI côte à côte, comme sur Retail 9.4. Réinitialiser TOUT demande maintenant de taper Confirm. Optimiser mes FPS et graphismes a disparu : les réglages graphiques qu'il modifiait n'existent pas sur ce client."
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "Comme sur Retail 9.4, chaque carte d'apparence de la page Style a un menu des modules qui l'utilisent : cochez des modules d'une autre apparence, puis appuyez sur Appliquer les styles pour tous les basculer en un seul rechargement. Les menus ne listent que les apparences que ce client peut dessiner : Gestionnaire de recharge, Minicarte et Compteurs de dégâts proposent EllesmereUI et Interface WoW Classic, Barres d'auras du joueur a disparu, et Appliquer à tous ignore les modules sans cette apparence."
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "La page d'importation peut mettre à jour votre profil actuel au lieu d'en créer un nouveau : cochez Importer dans le profil actuel et les modules sélectionnés de la chaîne (par exemple seulement les barres d'info) y remplacent leurs réglages tandis que le reste du profil est conservé."
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "La page Équipe EUI s'ouvre avec des remerciements à Ellesmere et la carte de l'équipe du portage avec un lien GitHub vers les versions. La ligne d'en-tête qui crédite Ellesmere l'ouvre."
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "Les rappels de sorts personnalisés, la visibilité et les sons sont enregistrés séparément pour chaque personnage, indépendamment des profils partagés."
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "Filtres optionnels pour les hauts faits, le commerce et le recrutement de guilde, plus vos propres mots et phrases bloqués."
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "Configurez le délai de répétition, la correspondance des expéditeurs et les canaux de discussion depuis la nouvelle page Filtre anti-spam."
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "Menus de contour dans les roues dentées des textes des barres d'info et des cadres d'unité, et Contour du texte de zone dans Confort de jeu. L'aperçu des cadres d'unité montre le contour de chaque texte."
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "Nouvelles sections FAMILIERS et RENDEMENTS DÉCROISSANTS, plus Estomper hors de portée et son opacité sous Cible et visibilité."
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "Annoncer les interruptions et Accepter les invitations des amis et de la guilde dans la section GROUPE, et un bouton Dissoudre le groupe dans les Outils raid."
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "Affichage de la barre, Menu, Sacs et barres d'EXP et Animations de barre, avec un aperçu en direct de la barre sélectionnée. Cliquez sur une icône, un raccourci ou un nombre pour aller à son réglage."
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "Les pages Raid et Groupe reçoivent la section DISSIPATIONS de Retail et un Mode aperçu (Réel, Superposition ou Pas d'aperçu) en haut."
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "Les pages Groupe et Raid reçoivent une section SORTS CIBLÉS : mode, aperçu, taille des icônes, nombre maximal d'icônes, position, croissance, décalages, balayage d'incantation, chrono d'incantation et couleurs d'interruptibilité."
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "Les cadres de raid (Groupe et Raid) et les cadres d'unité (joueur, cible, focalisation) reçoivent une section ABSORPTIONS pour les boucliers estimés, avec un bouclier dans l'aperçu des cadres d'unité."
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "Barres CDM s'ouvre maintenant avec le menu déroulant de barres de Retail (renommer ou supprimer des barres personnalisées, ajouter des barres Recharges, Utilitaire, Améliorations ou FocusKick) et les icônes de la barre sélectionnée : glissez pour réordonner, cliquez sur une icône pour la modifier, clic du milieu pour la retirer, et utilisez + pour ajouter des sorts ou des améliorations."
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "Masque les annonces du serveur comme \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", en gardant éventuellement visibles les morts à partir d'un niveau choisi."
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "Le Son d'incantation FocusKick et les sons de discussion listent les sons EllesmereUI et SharedMedia, et la page Textures relie les Compteurs de dégâts à la Texture de barre de chaque fenêtre"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "Nouveau menu déroulant en haut d'Icônes, avec un lien pour l'appliquer à chaque barre. L'aperçu montre la forme."
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "Icône d'affaiblissement de boss, Taille de l'icône, Décalage Y de l'icône et Afficher dissipable sans affaiblissement de boss sous Dissipations"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "Sections Général, Disposition, Vie et ressource, Texte, Icônes, Barre d'incantation et Cible et visibilité"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "Réglages Affichage, Extras et Inventaire Wrath, dont Supprimer le personnage enregistré"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "Thèmes d'icônes de classe, noms aux couleurs de classe, bordures, couleurs d'accent, bannières de faction et acceptation automatique des invitations"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "Affichage, Couleurs, Général et Filtres d'aura avec nuanciers intégrés et menus à roue dentée"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "Ramassage rapide, Remplir auto la confirmation de suppression, Réparation auto et Vendre la camelote auto dans la disposition Retail"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "Sections Affichage, Couleurs et Extras avec nuanciers intégrés et roues dentées d'acceptation et de remise automatiques"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "Icônes de sorts Wrath, vrais temps d'incantation et les mêmes illustrations de faction et de portrait que les cadres réels"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "Le menu déroulant Profil actif affiche de nouveau les icônes de renommage, de suppression et de raccourci sur chaque profil."
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "Les menus déroulants s'ouvrent de nouveau avec !!!ClassicAPI installé ; sa fonction de découpage ne déplace plus les menus dans un cadre de défilement vide."
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "La réinitialisation des Réglages globaux ne s'arrête plus à mi-chemin sur une erreur et recharge de nouveau l'interface."
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "Les options sans effet sur le client Wrath sont masquées : netteté d'image, Tolérance de latence, Taille du texte de combat, atténuation de Prompte guérison, contour Slug, mode sombre et couleurs des ressources de classe, couleurs de classe et de ressource propres à Retail, et textures d'anneau du curseur."
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "Réglages globaux n'affiche plus la page Manette, qui n'a rien à contrôler sur le client Wrath."
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "Distance de caméra max enregistre et conserve sa valeur au lieu de revenir à 1.0, et monte jusqu'à 4 comme le permet le client Wrath."
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "Barres CDM et Barres de suivi s'ouvrent sans l'erreur \"attempt to call field 'disabled'\", et neuf options affichent de nouveau leurs infobulles."
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "Discussion > Filtre anti-spam : les réglages de type de discussion restent utilisables quand seul le filtre de commerce ou de recrutement est actif, et les infobulles expliquent ce que chacun couvre."
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "L'ouverture des options n'expose plus les actions Blizzard ultérieures à un blocage au nom d'EllesmereUI."
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "Les menus à cases comme Visibilité cochent et décochent leurs cases dès le clic, même quand la mise à jour en direct du module rencontre un problème, au lieu de seulement après fermeture et réouverture du menu."
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "Les listes déroulantes, listes à cases et autres fenêtres d'options dessinent leurs éléments au-dessus de leur propre fond, sur un fond opaque, au lieu d'afficher des éléments délavés avec la page qui transparaît."
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "La page Style conserve maintenant les couleurs de vie des cadres d'unité par apparence, donc passer de l'interface WoW Classic à l'apparence EllesmereUI conserve les couleurs de chacune."
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "L'aperçu des cadres d'unité et les nuanciers de couleur de ressource affichent les couleurs de ressource d'origine du jeu sous l'interface WoW Classic."
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "Chaque ligne de Positions du texte principal, Nom du sort, Chrono d'incantation et Noms amicaux a maintenant sa propre roue dentée pour le contour au lieu de le cacher dans la fenêtre de taille."
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "Appuyer sur Échap pour fermer les fenêtres Blizzard n'affiche plus \"EllesmereUIOptions has been blocked from an action\"."
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "Les options de dégâts, soins, effets périodiques et dégâts du familier en combat utilisent les propres réglages de texte de combat de Wrath."
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "Les widgets d'options masqués ne prennent plus le focus clavier après la fermeture d'autres fenêtres avec Échap."
L["Dragging or typing in a slider no longer errors."] = "Faire glisser un curseur ou y saisir une valeur ne provoque plus d'erreur."
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "Le panneau de réglages s'ouvre sur les clients dont la recherche d'atlas provoque une erreur sur les noms inconnus, au lieu d'échouer avec une erreur 'NS'."
L["Displays has a ZONE TEXT section with Move Zone Text."] = "Affichages a une section TEXTE DE ZONE avec Déplacer le texte de zone."
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "Les Outils raid n'ont plus de section BARRES DE BOSS MOD : les options Sources d'AbilityTimeline masquent les barres DBM et BigWigs."
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "Le panneau de raid de Retail : affichez-le jamais, en raid, dans n'importe quel groupe ou toujours, en Bande compacte redimensionnable, en une ou deux fenêtres, ou une seule partie. Il peut démarrer en petite icône, s'ouvre et se ferme avec un raccourci même en combat, et dispose de trois comptes à rebours de pull, de Convertir et de Dissoudre. Réinviter retire tout le monde et le réinvite dans le même type de groupe, et Convertir en groupe reconstruit de la même façon un raid de cinq joueurs ou moins en groupe. Maj + Clic gauche sur un marqueur pour placer son marqueur au sol quand l'objet du marqueur est dans vos sacs, ou Maj + Clic gauche sur l'icône d'effacement pour réinitialiser les marqueurs au sol. En raid, il ne s'affiche que pour le chef et les assistants."
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "Une touche lance Détournement ou Ficelles du métier sur votre focalisation, le tank (nom saisi, tank principal ou rôle de tank), votre cible amicale ou votre familier. Une icône indique qui le recevra, le chrono de l'amélioration et la recharge. Liez-la dans Raccourcis."
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "Les dégâts subis, soins, évitements et entrées ou sorties de combat défilent au-dessus du cadre du joueur au lieu du texte de combat de Blizzard, avec les animations Droit, Fontaine ou Statique, des couleurs par type et un déplaceur en mode Déverrouillage."
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "Choisit pour vous l'unique option de dialogue d'un PNJ. Maintenez Maj pour l'ignorer ; les instances et les PNJ ayant des quêtes à prendre ou à rendre sont laissés tranquilles. Sa roue dentée peut aussi ignorer les quêtes de bas niveau."
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "Une flèche à côté du champ Destinataire liste vos rerolls de ce royaume et de cette faction, les membres de la guilde et les derniers noms à qui vous avez écrit. Cliquez sur un nom pour le saisir."
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "Choisissez Aucun, Contour, Contour épais ou Ombre pour le texte de zone, de sous-zone et JcJ affiché en entrant dans une zone. Défaut Blizzard conserve la police propre au jeu."
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "Annonce le sort que vous ou votre familier avez interrompu, avec un lien de sort, en Dire, Emote, Groupe ou Raid. Groupe et Raid passent au canal de champ de bataille dans les champs de bataille."
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "Les invitations de groupe de votre liste d'amis et des membres de votre guilde sont acceptées automatiquement, sauf si vous êtes déjà groupé ou en file d'attente de l'Outil Donjons."
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "Un bouton Dissoudre dans les Outils raid retire tout le monde de votre raid ou groupe après confirmation. Chef uniquement, jamais en combat."
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "Ramasse tout instantanément même avec le butin automatique de Blizzard désactivé ; maintenez Maj pour voir la fenêtre de butin. Les emplacements verrouillés comme les jets de groupe et le maître du butin sont ignorés."
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "IPS et latence, stats secondaires, alerte de durabilité, alertes de combat et de mort, un réticule et un nouveau texte de distance de la cible, tous déplaçables en mode Déverrouillage."
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "La nouvelle Couleur du texte par défaut du compteur d'IPS, Qualité, colore les IPS et chaque valeur de latence en vert, jaune ou rouge (60/30 fps, 100/250 ms). Personnalisée et Couleur de classe restent disponibles."
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "Les sons d'alerte des packs SharedMedia chargés après Confort de jeu sont aussi joués"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "Un bouton Tout ouvrir récupère les objets et l'or lettre par lettre, en ignorant les envois contre remboursement et les courriers de MJ"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "Avec Envoyer un courrier ouvert, Maj-clic sur un objet du sac pour le joindre ainsi que les objets correspondants"
L["Opens lootable containers one at a time out of combat (off by default)"] = "Ouvre les conteneurs à fouiller un par un hors combat (désactivé par défaut)"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "Un bouton Tout apprendre à côté d'Apprendre indique le nombre de sorts disponibles et le coût total"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "Durée du pull, diffusion DBM/BigWigs et un compte à rebours dans la discussion"
L["Raid Tools keeps its size after importing a Retail profile."] = "Les Outils raid conservent leur taille après l'importation d'un profil Retail."
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "Le Maj-clic pour joindre au courrier ne remplace plus le gestionnaire de clic des objets du sac, les clics dans les sacs restent donc exempts de corruption."
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "Le masquage des barres DBM et BigWigs quand AbilityTimeline est actif a été déplacé dans AbilityTimeline lui-même, comme sur Retail : Hide DBM bars et Hide BigWigs bars sur sa page Sources. L'option des Outils raid a disparu."
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "Se déconnecter, quitter, libérer l'esprit et les autres fenêtres de confirmation de Blizzard ne déclenchent plus le message \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\"."
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "Le nom de la zone n'apparaît plus au milieu de l'écran aux petites échelles d'interface. Il est maintenant fixé en haut (X 9 / Y 322 depuis le centre de l'écran), sans déplaceur en mode Déverrouillage."
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "Afficher les améliorations du joueur place les améliorations du joueur survolé en icônes à côté de l'infobulle, avec position, taille, icônes par ligne et décalages."
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "Survoler une stat dans la barre latérale de la feuille de personnage fait briller les objets équipés qui la donnent."
L["Inspect Enchants and Missing Enhancements"] = "Enchantements à l'inspection et améliorations manquantes"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "Les enchantements à l'inspection s'affichent en icône avec le nom au survol, ou en noms teintés selon la qualité de l'objet, avec leur propre taille. Au niveau maximum, des badges rouges signalent les enchantements manquants, les châsses vides et une boucle de ceinture manquante, comme sur votre feuille de personnage."
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "Enregistrer un ensemble d'équipement reconstruit le sélecteur d'icône natif même s'il est déjà ouvert, évitant l'erreur de comparaison nil de PaperDollFrame."
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "Les boutons Besoin, Cupidité, Désenchanter et Passer des jets de butin comptent ce que le reste du groupe a choisi. Survolez un bouton pour voir qui, aux couleurs de classe."
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "Les infobulles des joueurs affichent le GearScore aux couleurs de GearScoreLite, avec sa formule quand il est chargé. La propre ligne de GearScoreLite est conservée quand son option est activée."
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "Enchantements et gemmes sur chaque emplacement, durabilité la plus basse, rotation, panoramique et zoom du modèle, sections de stats réordonnables et une bande de châsses qui remplit les châsses depuis vos sacs."
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "Noms et barre de vie aux couleurs de classe, rang de guilde, cible, niveau d'objet et ancrage au curseur ou fixe"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "Niveaux d'objet à l'inspection, ancrage à côté de la fenêtre du personnage et mode liste pour les marchands"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "Lueur d'acceptation de résurrection et barre de compte à rebours Donjon prêt"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "Les fenêtres Collections et Garde-robe et transmogrification du serveur rejoignent les habillages de fenêtres"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "Salon de coiffure, JcJ et maîtres de guerre, Greffier d'arène, score des champs de bataille, minicarte et barre de capture, Aide et tickets MJ, statut de discussion MJ, chronos de respiration et de fatigue, chronomètre, cadres détachés de raid, outils de débogage et fenêtres de configuration Ace3"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "Les appels ne laissent plus de panneau noir vide pour le chef ou après votre réponse."
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "L'onglet Titres de la feuille de personnage liste de nouveau vos titres connus ; cliquez sur l'un d'eux pour le porter."
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "La fenêtre du message du jour de la guilde (et les autres fenêtres de texte larges) ne recouvre plus son titre et ses boutons avec la zone de saisie."
L["The Achievements window no longer darkens the achievement list behind its border."] = "La fenêtre des hauts faits n'assombrit plus la liste des hauts faits derrière sa bordure."
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "L'option d'habillage de la fenêtre Liste des addons ne s'affiche que si le client a une fenêtre Liste des addons."
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "Envoyer un courrier affiche de nouveau les champs Destinataire, Objet et message, et le curseur de saisie reste visible dans les zones de saisie habillées."
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "L'ancrage fixe de l'infobulle ne revient plus à sa position enregistrée pendant que vous le faites glisser en mode Déverrouillage."
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "Hôtel des ventes : les panneaux et onglets ajoutés par Auctionator et d'autres addons d'enchères conservent leur propre apparence et disposition, et les boutons Fermer du pied de page n'ont plus de \"x\" sur leur texte."
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "Talents : le bouton de fermeture et le pied de page des points s'arrêtent à la barre de défilement au lieu de dépasser le bord de la fenêtre."
L["Window tabs keep their dark background instead of showing through."] = "Les onglets des fenêtres conservent leur fond sombre au lieu de laisser voir au travers."
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "Carte du monde : la flèche du joueur, les points de groupe et de raid, le cadavre et les marqueurs de quête restent sur l'illustration de la carte après un changement de vue en combat, y compris sur les cartes d'instance."
L["Native dropdown menus no longer show an empty square at the right of each row."] = "Les menus déroulants natifs n'affichent plus de carré vide à droite de chaque ligne."
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "Les listes déroulantes des fenêtres Blizzard, comme le type de l'Outil Donjons, s'arrêtent à leur flèche au lieu de dépasser le bord de la fenêtre."
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "Informations de raid : le fond couvre toute la fenêtre, y compris le titre, le bouton de fermeture, la dernière ligne et les boutons Prolonger le verrouillage de raid et Fermer."
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "Le fond des Talents et Glyphes s'arrête maintenant au-dessus des onglets et à côté des onglets de double spécialisation."
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "L'onglet Glyphes affiche de nouveau son fond de parchemin natif, aligné avec les emplacements de glyphe."
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "Les curseurs des fenêtres Blizzard, comme dans les options Caméra et Souris, retrouvent leur taille normale."
L["Hide Until Usable and Hide Outside Form/Stance"] = "Masquer jusqu'à utilisable et Masquer hors forme/posture"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "Nouveaux États de recharge : Masquer jusqu'à utilisable n'affiche un sort que lorsqu'il peut être lancé et est hors recharge (Fulgurance, Revanche, Ivresse de la victoire, Exécution) ; le manque de ressources ne le masque pas. Masquer hors forme/posture ne l'affiche que dans la forme ou posture requise. Les deux peuvent refermer l'espace ou garder la place."
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "Le menu + ajoute un Emplacement vide qui garde une position libre sur la barre, pour grouper les icônes."
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "Les barres peuvent passer à un balayage Façonné qui suit les icônes rondes et prend une Couleur de balayage, au lieu du balayage carré sombre du client."
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "Barres Recharges, Utilitaire et Améliorations plus des barres personnalisées et une barre FocusKick, suivies depuis votre grimoire, vos recharges et vos auras. Les listes sont enregistrées par groupe de talents."
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "Barres d'aura ou de recharge pour le joueur, la cible, la focalisation ou le familier avec textures, dégradés, repères de cumuls et lueur pandémique, organisées en groupes."
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "Les boutons + au-dessus des icônes de barre ouvrent le menu d'ajout de Retail : sort, objet ou emplacement personnalisé, bijoux, raciaux, potions et vos sorts appris, ou améliorations et préréglages d'améliorations depuis le + doré"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "Les bijoux à effet passif dans les emplacements de bijou affichent leur icône et la recharge interne après chaque déclenchement, avec l'amélioration déclenchée tant qu'elle dure"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "Les textures des barres de suivi incluent SharedMedia, et le Son d'incantation FocusKick ajoute les sons EllesmereUI et SharedMedia à ceux de Blizzard"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "Illumine les boutons d'action EllesmereUI, Blizzard ou ElvUI tant qu'une aura est active ou absente"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "Toujours afficher, atténuer, masquer en recharge ou quand prêt, et faire briller quand prêt"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "Raciaux, pierres de soins, potions Wrath et améliorations comme Héroïsme et Furie sanguinaire"
L["Show an entry only when a chosen talent is learned"] = "N'affiche une entrée que lorsqu'un talent choisi est appris"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "Les options de la barre Utilitaire ne passent plus à Améliorations après un clic, et la barre Recharges n'est plus remplacée par une seconde barre Améliorations."
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "Les raciaux s'affichent une seule fois : la barre Utilitaire ne liste plus Torrent arcanique (et les autres raciaux à variantes de classe) trois fois."
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "Un bijou passif dans un emplacement de bijou affiche sa propre icône dans les options au lieu d'un point d'interrogation."
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "Les barres enregistrées en double ou sous le nom d'une autre barre (deux barres Améliorations et aucune Recharges) sont réparées, chaque barre intégrée conserve donc ses propres icônes et options."
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "Barres en Taille auto et Répartition égale avec fonds, bordures et aimantation aux bords de l'écran de Retail, plus marges, alignement, échelle et couleurs par bloc."
L["20 Wrath Blocks"] = "20 blocs Wrath"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "Horloge, IPS, latence, emplacement, historique de l'or, sacs, durabilité, EXP et réputation, double spécialisation, métiers, voyage, micro-menu, monnaies et plus."
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "Le texte de latence est vert, jaune ou rouge selon la qualité de la connexion par défaut. Un nuancier Latence dans Couleur du texte y revient après avoir choisi une autre couleur."
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "Infobulles en colonnes avec lignes cliquables et lignes sécurisées de sort, d'objet et de macro"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "Chaque barre a un déplaceur dont les Options de l'élément ouvrent les réglages de cette barre"
L["Profiles from 0.2 are converted automatically"] = "Les profils de la 0.2 sont convertis automatiquement"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "Les barres aimantées à un bord de l'écran ou réglées en pleine longueur démarrent à leur place après la connexion au lieu de nécessiter d'ouvrir et fermer le mode Déverrouillage."
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "La zone de latence de la barre d'incantation fonctionne pour les sorts en file d'attente et reste visible pendant les canalisations, avec une couleur et un texte en millisecondes configurables."
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "Barres de classe, de ressource et de vie, Barre d'incantation, Barre de GCD, Chrono de frappe et Barre des totems, chaque élément avec son propre déplaceur en mode Déverrouillage. Les anciens profils migrent une fois."
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "Frappes de main droite, de main gauche et à distance depuis le journal de combat, avec Frappe héroïque, Enchaînement et Mutiler en file d'attente, la hâte de parade et les changements de vitesse."
L["Bar textures include textures from SharedMedia and other addons"] = "Les textures de barre incluent celles de SharedMedia et d'autres addons"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "Barres verticales, textes Retail, dégradés, seuils, repères et lissage"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "Ordre et comptes à rebours des runes du chevalier de la mort, points de combo, ou les illustrations propres à Blizzard"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "Ticks de canalisation, latence, durée totale et couleurs non interruptibles"
L["Totem icons and timers, and a movable Call Totem Bar"] = "Icônes et chronos des totems, et une barre d'appel des totems déplaçable"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "La barre d'appel des totems ne se redimensionne ni ne bouge plus pendant le combat ; les changements s'appliquent à la fin du combat."
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "La barre d'incantation du joueur affiche le nom du sort canalisé au lieu de \"Channeling\"."
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "Icônes de classe dans les thèmes EUI, orbes d'état, notes dans la ligne de détails, bannières de faction et surbrillance au survol, avec bordures et couleurs d'accent."
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "Accepte les invitations de groupe des amis, et éventuellement des membres de la guilde, et ferme la fenêtre."
L["The window stays native but rows still get class icons and colored names"] = "La fenêtre reste native mais les lignes reçoivent quand même des icônes de classe et des noms colorés"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "Accepter auto prend les quêtes des dialogues de PNJ, avec Empêcher l'acceptation multiple de quêtes, et Rendre auto termine les quêtes à récompense unique. Maintenez Maj pour ignorer."
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "Utilise l'objet de votre quête suivie, trouvé dans le journal de quêtes, et ne retient la touche que tant qu'il y a un objet à utiliser."
L["The top line uses the accent color and Line Color tints the header divider"] = "La ligne du haut utilise la couleur d'accent et Couleur de ligne teinte le séparateur de l'en-tête"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show, /eqt hide et /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "Effacez votre focalisation en cliquant sur le cadre de focalisation (Maj + Clic droit par défaut, ou Ctrl/Alt + Clic droit, Clic du milieu, Maj + Clic gauche). Réglez-le sur la page du cadre de focalisation. Fonctionne en combat."
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "Deux nouveaux modes de filtre des affaiblissements : Affaiblissements de raid affiche les affaiblissements de raid courants de n'importe qui (armure, dégâts des sorts et physiques subis, critiques subis, puissance d'attaque, vitesse d'attaque et d'incantation, soins reçus, Jugements et Marque du chasseur), et Affaiblissements personnels et de raid y ajoute les vôtres."
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "Position de l'icône de type place l'icône du type d'affaiblissement dissipable le plus important du joueur sur un point de la barre de vie, avec sa taille et ses décalages dans la roue dentée. Dissipables par vous uniquement se trouve maintenant à côté et restreint de la même façon la superposition, l'icône et les couleurs de bordure."
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "Le cadre de focalisation reçoit les réglages Style de bordure, taille et couleur des auras, comme le joueur et la cible."
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "Le joueur, la cible et la focalisation affichent les soins entrants au-delà du remplissage de vie : les vôtres et ceux des autres joueurs dans leurs propres couleurs, depuis LibHealComm-4.0 (seuls les soigneurs utilisant un addon HealComm sont vus)."
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "Les filtres d'affaiblissements peuvent maintenant afficher ou masquer Rassasié, Épuisement et les autres affaiblissements de blocage de Furie sanguinaire. Ils restent masqués par défaut."
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "Les textes Gauche, Droite, Centre et Supplémentaire, les textes de la barre de texte inférieure et le % de ressource ont chacun un choix de contour sous Taille : Aucun, Contour, Contour épais ou Ombre, ou la valeur par défaut du module."
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "Ancrage, croissance, icônes par ligne, texte de durée et de cumuls, bordures texturées et anneaux de dissipation. La cible et la focalisation reçoivent la Lueur des améliorations purgeables."
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "Chaque style d'indicateur de combat s'affiche maintenant, et les portraits en surbrillance épousent leur forme au lieu de déborder."
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "Les barres de vie du joueur, de la cible, de la focalisation et des boss affichent les boucliers de dégâts estimés avec Style d'absorption, Opacité, Couleur, Placement, Afficher le sur-bouclier et Afficher sur les cadres de boss de Retail"
L["Mana or Mana + Form Power, with a separate form bar"] = "Mana ou Mana + ressource de forme, avec une barre de forme séparée"
L["Threat %, a pet power bar and the pet happiness icon"] = "Menace %, une barre de ressource du familier et l'icône de bonheur du familier"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "Indicateurs d'aura regroupés sur la barre de vie avec Utiliser la disposition d'indicateurs"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "Superpositions de remplissage, pleines, en dégradé et en dégradé net à la couleur de dissipation"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "Sous l'interface WoW Classic et le style Blizzard, la couronne de chef se place dans le coin supérieur du portrait, comme sur les cadres d'origine, au lieu de dans la barre de vie."
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "L'icône de chef de groupe sur les cadres d'unité s'affiche uniquement sur le chef au lieu de plusieurs membres du groupe."
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "Définir la focalisation et Effacer la focalisation dans le menu du clic droit des cadres d'unité fonctionnent hors combat sans la fenêtre « bloqué pour une action » ; en combat ils sont masqués."
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "Les barres et portraits des cadres d'unité ne sont plus déplacés dans des cadres de défilement quand !!!ClassicAPI est installé."
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "La Lueur des incantations importantes est masquée pour les barres d'incantation de la cible et de la focalisation ; le client Wrath ne peut pas savoir quels sorts sont importants."
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "Les barres d'incantation canalisée affichent le nom du sort au lieu de \"Channeling\"."
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "Les cadres de boss mettent maintenant à jour la vie, la ressource et le texte quand le boss n'est ni votre cible ni votre focalisation."
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "Les conditions de visibilité (combat, groupe et masquage sans cible) s'appliquent maintenant aux cadres au lieu de s'arrêter sur une erreur, et les cases du menu Visibilité se cochent donc immédiatement."
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "Les barres de ressource de l'interface WoW Classic restent maintenant dans l'illustration du cadre : le rebord de l'illustration se dessine par-dessus la barre de ressource comme sur la barre de vie."
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "L'interface WoW Classic donne maintenant à chaque cadre d'unité la barre de vie verte d'origine au lieu des couleurs de classe. Revenir à l'apparence EllesmereUI restaure vos couleurs."
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "Les barres de ressource de l'interface WoW Classic utilisent les couleurs d'origine du jeu (mana bleu profond, rage rouge, énergie jaune) au lieu de la palette EllesmereUI. Les autres apparences conservent la palette."
L["Text outlines now apply to the live frames, not only the options preview."] = "Les contours de texte s'appliquent maintenant aux cadres réels, pas seulement à l'aperçu des options."
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "Les cadres d'unité n'échouent plus au chargement sur les configurations dont les textures de masque reviennent vides (erreur de barre d'absorption à la connexion)."
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "Les icônes affichées par ID de sort affichent la bonne icône ou un point d'interrogation, jamais un carré vide."
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "L'indicateur de faction ne provoque plus d'erreur en mode mercenaire, et les styles JcJ propres à Retail utilisent l'icône JcJ de Wrath."
L["Level text no longer errors with Font not set when frames are first created."] = "Le texte de niveau ne provoque plus l'erreur Font not set à la première création des cadres."
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "Comme sur Retail 9.4, la section Barre d'expérience s'ouvre avec Style de barre d'EXP : EllesmereUI pour la barre EUI, Luxthos pour la barre EUI dans la disposition de la WeakAura Luxthos, ou Défaut Blizz pour les barres d'EXP et de réputation de Blizzard. Il remplace Activer la barre d'expérience et le bouton Appliquer la disposition Luxthos."
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "Comme sur Retail 9.4, toute barre horizontale peut afficher les griffons classiques à son extrémité gauche, droite ou aux deux, depuis le menu Embouts à la fin de DISPOSITION. La roue dentée règle leur taille et leurs décalages, et Appliquer à tous les copie sur chaque barre. L'aperçu en direct les affiche aussi."
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "La barre d'EXP reçoit la Superposition de l'EXP de quête de Retail (quêtes terminées en vert, inachevées en doré), des séparateurs avec Repères intelligents, des remplissages en dégradé, des couleurs de fond et de repos, et sept positions de texte affichant les valeurs, l'EXP des quêtes terminées, l'EXP par heure, le temps avant le niveau suivant et le temps de jeu. Appliquer la disposition Luxthos recrée la populaire WeakAura de barre d'EXP de Luxthos, avec Afficher au niveau maximum, une étincelle et l'EXP de repos après l'EXP de quête."
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "Les boutons contenant un objet équipé, comme un bijou, peuvent afficher une bordure de la couleur de sa rareté. Désactivé par défaut."
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "Quatre barres supplémentaires, désactivées par défaut, chacune avec ses propres raccourcis, son déplaceur en mode Déverrouillage et tous les réglages d'Affichage de la barre. Les guerriers, druides, voleurs et prêtres voient quelle posture ou forme partage les emplacements d'une barre."
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "Cercle et Portrait dessinent des icônes rondes, Losange, Hexagone et Bouclier découpent l'icône à la forme, et Carré et Carré arrondi ajoutent un contour façonné. Réglable par barre, y compris familier et posture."
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "Tapez /kb, survolez un bouton et appuyez sur une touche pour la lier, y compris les modificateurs, les boutons de souris et la molette. Le clic droit efface ; Annuler ou Échap annule."
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "Texte, bordures, fonds, orientation et croissance par barre, les animations de bouton et le moteur de visibilité de Retail, et le changement de page de la barre 1 par modificateur."
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1 s'affiche S1, Control+1 C1, les boutons de souris M4 et la molette MwU/MwD"
L["Shrink the bag bar to a single backpack button"] = "Réduit la barre de sacs à un seul bouton de sac à dos"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "Micro-menu et barre de sacs carrés, barres d'EXP et de réputation plates et améliorations et affaiblissements déplaçables"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "Les flèches de page de la barre 1 changent de page sans le message \"blocked from an action only available to the Blizzard UI\"."
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "Changer de posture ne fait plus apparaître de barre de posture et de familier Blizzard en double."
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "Les sorts peuvent être déposés sur la barre 1 pendant que l'illustration de la barre Blizzard est masquée."
L["Player Buffs keep growing downward as rows are added."] = "Les améliorations du joueur continuent de s'étendre vers le bas à mesure que des lignes s'ajoutent."
L["The XP and reputation bars no longer error on their first update."] = "Les barres d'EXP et de réputation ne provoquent plus d'erreur lors de leur première mise à jour."
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "Les rappels de Création de pierre d'âme, y compris les rappels de sorts personnalisés, n'apparaissent que pour les démonistes."
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "Un rappel réservé au Sacré pour votre Sceau de sagesse, y compris quand un autre sceau est actif."
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "Un clic lance votre amélioration de groupe, comme Robustesse, Don du fauve ou Intelligence des Arcanes, à son rang le plus élevé sur le premier membre qui ne l'a pas."
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "Auras, présences, aspects, boucliers, imprégnations d'arme, poisons, familiers, Pierre d'âme et Pierre de soins, plus flacon, élixir et nourriture avec le nombre dans les sacs."
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "Les sons de rappel incluent les sons SharedMedia, même ceux des packs chargés plus tard"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "Monde, donjons et raids normaux et héroïques, ou en combat, avec les chronos Afficher en dessous"
L["Talent reminders for Wrath zones and your current instance"] = "Rappels de talents pour les zones Wrath et votre instance actuelle"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "Vos propres rappels par ID d'aura et un avertissement de mana des soigneurs à l'appel"
L["Middle-click hides a reminder until the next loading screen"] = "Le clic du milieu masque un rappel jusqu'au prochain écran de chargement"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "Désactiver Runeforge masque maintenant le rappel de rune du chevalier de la mort."
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "Ajouter des zones à un ancien rappel de talent ne provoque plus d'erreur, et les nouvelles zones s'appliquent immédiatement."
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "Une pièce dans l'en-tête du sac marque les objets comme camelote : cliquez dessus, puis cliquez sur des objets. Les objets gris et marqués vont dans une catégorie Camelote, et un bouton Vendre la camelote apparaît à côté de la pièce chez les marchands. Sa roue dentée ajoute un badge pièce sur les objets marqués."
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "Les raccourcis des sacs ouvrent et ferment la disposition existante en combat. Les rafraîchissements de disposition attendent la fin du combat."
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "Une barre latérale avec les vues Tous les objets, OneBag et MultiBag, les objets épinglés et récents, les catégories Retail pour les objets Wrath et vos propres catégories."
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "OneBag fusionne les piles et trie par type de sac, MultiBag trie chaque sac, avec Trier en bas et Mélanger."
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "Une roue dentée à côté de la recherche ouvre les options des Sacs, ou la page Banque à la banque"
L["Each saved character in the Characters list has an x to delete its data"] = "Chaque personnage enregistré dans la liste Personnages a un x pour supprimer ses données"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "Bordures de qualité, marques de quête, niveau d'objet, texte LqE, noms d'ensembles et camelote atténuée"
L["Group the bank by category, with a sidebar"] = "Regroupe la banque par catégorie, avec une barre latérale"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "Avec Activer les sacs désactivé, les fonctions de sac par défaut ne sont plus remplacées, ce qui évite les erreurs d'action bloquée dues à du code de sac corrompu."
L["Opening the Characters list no longer errors."] = "L'ouverture de la liste Personnages ne provoque plus d'erreur."
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "Les annonces de vente d'or avec sites web ou prix en argent réel, y compris 5000G=20 bucks et les adresses W.W.W déguisées, sont filtrées par défaut dans les canaux de discussion sélectionnés."
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "Les avis de canal serveur non pris en charge comme NOT_IN_LFG ne provoquent plus d'erreur du formateur de discussion natif."
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "Filtrage anti-spam optionnel avec fenêtre de répétition, correspondance des expéditeurs et contrôles public, groupe ou chuchotement."
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "Fond, séparateur, position de la saisie, bordure et onglets Retail sur le dock natif, plus une barre latérale avec amis, guilde, copie, canaux et réglages."
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "Horodatages Retail, noms de canaux courts, noms aux couleurs de classe, infobulles des liens, sons des chuchotements, historique de discussion enregistré et fenêtres d'URL et de copie Retail."
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "Afficher les messages masqués liste les 200 dernières lignes masquées par le filtre anti-spam pendant cette session, avec l'heure, la raison, le canal et l'expéditeur. Effacer l'historique du filtre s'appelle maintenant Réinitialiser la mémoire des répétitions."
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "Le préréglage d'annonces commerciales masque aussi les annonces d'artisanat LFW (recherche de travail)."
L["Right-click the chat in Unlock Mode to open its Display settings"] = "Clic droit sur la discussion en mode Déverrouillage pour ouvrir ses réglages d'Affichage"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "Bulles de discussion restylées avec options par canal et masquage en instance"
L["The chat fades after a delay and comes back on mouseover"] = "La discussion s'estompe après un délai et revient au survol de la souris"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "Copier le chat copie l'onglet de discussion que vous regardez au lieu du dernier onglet sur lequel vous avez fait un clic droit, qui pouvait afficher \"(No chat history)\"."
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "Correction d'une erreur \"SetPoint(): is dependent on this\" lors du style de certaines bulles de discussion de PNJ."
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "Le filtre de recrutement de guilde ne masque plus les annonces de raid qui mentionnent une guilde, comme \"<Frost> LF 1 heal ICC25\" ; seules les phrases de recherche de guilde comptent."
L["GM whispers and messages are never hidden by the spam filter."] = "Les chuchotements et messages des MJ ne sont jamais masqués par le filtre anti-spam."
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "Les mots-clés du filtre anti-spam ignorent aussi la casse des lettres accentuées, donc promoção masque aussi PROMOÇÃO."
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "Les filtres d'annonces commerciales et de recrutement de guilde suivent le réglage Chat public, et le filtre anti-spam ne travaille pas tant que tous les filtres sont désactivés."
L["The sidebar shows on first load, and tabs and toggles update right away."] = "La barre latérale s'affiche au premier chargement, et les onglets et options se mettent à jour immédiatement."
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "La discussion principale garde sa position du mode Déverrouillage au lieu d'être réinitialisée par le dock."
L["A saved chat opacity of 0 resets once to the Retail default."] = "Une opacité de discussion enregistrée à 0 est réinitialisée une fois à la valeur par défaut de Retail."
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "Cartes carrées, rectangulaires, rondes et rondes texturées, avec taille et opacité de bordure, styles texturés et couleurs personnalisées, d'accent ou de classe."
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "Les boutons d'addons sont regroupés dans le menu volant Retail avec une grille, une direction de croissance et le Déplacement libre par Maj-glisser."
L["A vanilla ring and zone banner with native zoom buttons"] = "Un anneau vanilla et une bannière de zone avec les boutons de zoom natifs"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "Cases d'horloge et de zone dans dix positions, plus coordonnées, IPS et latence, et texte de difficulté"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "Guilde et amis en un coup d'œil ; le clic gauche chuchote, le clic droit invite"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "Les actions du menu ouvrent les fenêtres Blizzard par des appels sécurisés, évitant les erreurs d'action bloquée."
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "Choisissez Interface WoW Classic pour les Compteurs de dégâts sur la page Style : chaque fenêtre reçoit la bordure d'infobulle classique, une bande d'en-tête d'infobulle et des icônes d'en-tête vanilla, et conserve toutes les fonctions de compteur d'EllesmereUI."
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "L'infobulle de détail d'un sort affiche son ID de sort, et chaque ligne de sort de la fenêtre détaillée se termine par son ID."
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "Les absorptions de bouclier consommées comptent dans Soins prodigués et SPS quand le lanceur peut être identifié, avec une vue Absorptions effectuées."
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "Corps uni, en-tête d'accent, barres Atrocity et icônes d'en-tête pour Réglages, Segment, Type de compteur et Réinitialiser, avec jusqu'à cinq fenêtres."
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "Jusqu'à 15 sorts et les trois principales cibles au survol, récapitulatifs de mort avec la vie à chaque coup, et une vue de focalisation par joueur."
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "Les textures de barre SharedMedia se chargent qu'un profil les enregistre au format Compteurs de dégâts ou EllesmereUI"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "Une bande d'icônes et une fenêtre de barres de vos incantations, y compris celles ratées et interrompues"
L["A standalone combat timer with its own Unlock Mode element"] = "Un chrono de combat autonome avec son propre élément en mode Déverrouillage"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "Les fenêtres s'aimantent entre elles ; les fenêtres verrouillées ne peuvent pas bouger, être redimensionnées ni fermées"
L["Keybinds for Reset Data and Show / Hide Windows"] = "Raccourcis pour Réinitialiser les données et Afficher / masquer les fenêtres"
L["Specialization icons from talent data and paced group inspection"] = "Icônes de spécialisation tirées des données de talents et inspection du groupe espacée"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "Charge un menu d'actions uniquement dans votre groupe de talents principal ou secondaire, et permet à deux menus de partager un raccourci entre les spés."
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "Maintenez une touche, pointez ou faites défiler pour choisir, relâchez pour lancer. Jusqu'à 16 palettes de 20 entrées en disposition anneau, arc, éventail ou grille."
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "Une entrée Menu d'actions déploie jusqu'à 8 actions d'une autre palette, un niveau au-delà de l'anneau."
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "Couleur d'accent, de classe ou personnalisée pour l'entrée sélectionnée, l'aiguille et la surbrillance imbriquée"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "Réglez l'écart entre un menu imbriqué et son entrée, ainsi que la taille des icônes imbriquées"
L["Reverse which way a wheel tick moves the selection"] = "Inverse le sens dans lequel un cran de molette déplace la sélection"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "Assigner une touche capture la touche suivante avec ses modificateurs et demande confirmation avant de la réassigner"
L["Keep the menu open on release and fire with a Select key"] = "Garde le menu ouvert au relâchement et lance avec une touche Sélection"
L["Red when out of range, blue when short of power, grey when unusable"] = "Rouge hors de portée, bleu en manque de ressource, gris si inutilisable"
L["Elite and rare marks. Always in the same slot as the Quest Indicator."] = "Marques d'élite et de rare. Toujours dans le même emplacement que l'indicateur de quête."
L["Marks mobs for your active quests. Always in the same slot as the Rare Indicator."] = "Marque les monstres de vos quêtes actives. Toujours dans le même emplacement que l'indicateur de rare."
L["Quest Indicator"] = "Indicateur de quête"
L["Rare and Quest Indicators"] = "Indicateurs de rare et de quête"
L["Rare Indicator"] = "Indicateur de rare"
L["Rare/Quest Indicator"] = "Indicateur rare/quête"
L["Show In Instances"] = "Afficher en instance"
L["The Boss Icon slot is now the Retail Rare/Quest Indicator. It marks elites and rares, and mobs your active quests still need. Pick Rare Indicator, Quest Indicator or both in Core Positions; the slot cog adds Show In Instances."] = "L'emplacement Icône de boss devient l'indicateur rare/quête de Retail. Il marque les élites et les rares, ainsi que les monstres encore requis par vos quêtes actives. Choisissez Indicateur de rare, Indicateur de quête ou les deux dans Positions principales ; la roue crantée de l'emplacement ajoute Afficher en instance."
L["Crowd Control"] = "Contrôle de foule"
L["Crowd Control Slot"] = "Emplacement de contrôle de foule"
L["Debuffs + CC"] = "Affaiblissements + CC"
L["Crowd control on enemies (stuns, fears, polymorphs, roots, silences) gets its own Core Positions slot, from any caster, as on Retail. Or pick Debuffs + CC to show it first in the debuff row."] = "Le contrôle de foule sur les ennemis (étourdissements, peurs, métamorphoses, entraves, silences) a son propre emplacement dans Positions principales, quel que soit le lanceur, comme sur Retail. Ou choisissez Affaiblissements + CC pour l'afficher en premier dans la rangée d'affaiblissements."
L["A dark block no longer appears to the left of the health bar and grows as health drops (the heal absorb overlay, which 3.3.5 does not have)."] = "Un bloc sombre n'apparaît plus à gauche de la barre de vie en grandissant à mesure que la vie baisse (la superposition d'absorption de soins, absente de la 3.3.5)."
